def process_flowfile():
    flowFile = session.get()
    if flowFile is None:
        return

    # List of columns to process
    columns_to_process = ["district", "division", "upazila"]

    def to_title_case(input_string):
        return ' '.join([word.capitalize() for word in input_string.split()])

    # Loop through each column in the list
    for column in columns_to_process:
        column_value = flowFile.getAttribute(column)
        if column_value is None:
            column_value = ""  # Default to empty string if column is not found

        new_value = to_title_case(column_value)
        flowFile = session.putAttribute(flowFile, column, new_value)

    session.transfer(flowFile, REL_SUCCESS)

process_flowfile()

